// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { ORGANIC_LIMIT } from "../../../main/frontend/graph-explorer/graph-layout-engine.ts";
import { representativeResults } from "./fixtures/representative-graph.mjs";
import { answerToFrame } from "./support/large-graph-pipeline.mjs";

/**
 * Budgets for the Graph page's path from a query answer to the drawn, laid-out graph (parse, graph model, canvas
 * scope, layout, positions, and a frame of the large-graph canvas), on a representative graph of that many drawn
 * nodes. Up to `ORGANIC_LIMIT` nodes the organic engine lays the graph out (stress, fans, local search, routed
 * arrows); 1,000 nodes took about 10 s there before its code was optimized. GRAPH_PERFORMANCE_SLOWDOWN scales the
 * budgets for a slower machine; it is 1 by default.
 */
const SLOWDOWN = Number(process.env.GRAPH_PERFORMANCE_SLOWDOWN ?? 1) || 1;
const BUDGETS = [
  { nodes: 1_000, budgetMs: 4_000, attempts: 2 },
  { nodes: 5_000, budgetMs: 500, attempts: 3 },
  { nodes: 50_000, budgetMs: 5_000, attempts: 2 },
];

function degreeStats(graph) {
  const degree = new Map();
  for (const edge of graph.edges) {
    degree.set(edge.source, (degree.get(edge.source) ?? 0) + 1);
    degree.set(edge.target, (degree.get(edge.target) ?? 0) + 1);
  }
  const values = graph.nodes.map((node) => degree.get(node.id) ?? 0).sort((a, b) => a - b);
  return { isolated: values.filter((value) => value === 0).length, median: values[values.length >> 1], max: values.at(-1) };
}

function components(graph) {
  const parent = new Map(graph.nodes.map((node) => [node.id, node.id]));
  const find = (id) => {
    while (parent.get(id) !== id) {
      parent.set(id, parent.get(parent.get(id)));
      id = parent.get(id);
    }
    return id;
  };
  for (const edge of graph.edges) parent.set(find(edge.source), find(edge.target));
  return new Set(graph.nodes.map((node) => find(node.id))).size;
}

test("the representative graph is varied: hubs, hierarchies, communities, blank nodes, values and isolated nodes", async () => {
  const results = representativeResults(5_000);
  const { drawn, graph } = await answerToFrame(results);

  assert.equal(drawn.nodes.length, 5_000, "exactly the drawn nodes asked for");
  assert.ok(drawn.edges.length > 2.5 * 5_000 && drawn.edges.length < 4 * 5_000, `${drawn.edges.length} drawn edges`);
  const kinds = new Set(drawn.nodes.map((node) => node.kind));
  assert.deepEqual([...kinds].sort(), ["blank", "iri"]);
  assert.ok(graph.nodes.some((node) => node.kind === "literal"), "values are in the model but not drawn");
  assert.ok(drawn.nodes.every((node) => node.types?.length), "every drawn node carries its rdf:type as a colour");
  const degrees = degreeStats(drawn);
  assert.ok(degrees.max >= 150, `hubs: the largest degree is ${degrees.max}`);
  assert.ok(degrees.median >= 2 && degrees.median <= 8, `typical resources: median degree ${degrees.median}`);
  assert.ok(degrees.isolated > 0, "some resources have no drawn links");
  assert.ok(components(drawn) > 1, "more than one component");
  assert.ok(new Set(drawn.edges.map((edge) => edge.predicate)).size >= 10, "many predicates");
});

for (const { nodes, budgetMs, attempts } of BUDGETS) {
  test(`${nodes.toLocaleString("en")} nodes are laid out and drawn within ${budgetMs.toLocaleString("en")} ms`, async () => {
    const results = representativeResults(nodes);
    // The first run of a fresh process includes compiling the code; the page has done that before a large load.
    if (nodes <= 5_000) await answerToFrame(results);
    const runs = [];
    let outcome;
    for (let attempt = 0; attempt < attempts; attempt++) {
      outcome = await answerToFrame(results);
      runs.push(outcome.times);
      if (outcome.times.total <= budgetMs * SLOWDOWN) break;
    }
    const best = runs.reduce((left, right) => (right.total < left.total ? right : left));
    const report = runs.map((times) => Object.entries(times).map(([step, ms]) => `${step} ${Math.round(ms)}`).join(", "));

    assert.ok(best.total <= budgetMs * SLOWDOWN,
      `best of ${runs.length} took ${Math.round(best.total)} ms (budget ${budgetMs * SLOWDOWN} ms): ${report.join(" | ")}`);
    const { drawn, layout, frame } = outcome;
    assert.equal(drawn.nodes.length, nodes);
    assert.equal(layout.positions.size, nodes, "every drawn node is placed");
    if (nodes <= ORGANIC_LIMIT) assert.equal(layout.fanned, true, "the organic engine laid the graph out");
    for (const node of drawn.nodes) assert.ok(Number.isFinite(node.x) && Number.isFinite(node.y), node.id);
    const centres = new Set(drawn.nodes.map((node) => `${Math.round(node.x)},${Math.round(node.y)}`));
    assert.ok(centres.size > nodes * 0.99, `${nodes - centres.size} nodes share a centre`);
    assert.equal(frame.renderer, "webgl");
    assert.equal(frame.frames, 1, "one frame draws the whole graph");
    assert.ok(frame.drawnElements >= 2 * drawn.edges.length, "every edge is drawn");
  });
}
